window.MONSTER_CHUNK_120 = [{"name":"Quickling","cr":3,"xp":800,"alignment":"CE","size":"Small","type":"fey","init":7,"senses":[{"type":"low-light vision"}],"ac":19,"ac_touch":19,"ac_flat_footed":19,"ac_mods":"+7 Dex, +1 dodge, +1 size, +0 natural","hp":14,"hd":"4d6","hdvalue":4,"fort":1,"ref":11,"will":6,"defensive_abilities":["evasion","natural invisibility","supernatural speed","uncanny dodge"],"dr":"5/cold iron","weaknesses":["slow susceptibility"],"speed":[{"type":"land","speed":120}],"melee":"dagger +10 (1d3-1/19-20 plus poison)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dancing lights"},{"spell":"flare"},{"spell":"levitate"},{"spell":"shatter"},{"spell":"ventriloquism"}]}],"strength":8,"dexterity":24,"constitution":11,"intelligence":15,"wisdom":15,"charisma":14,"baseatk":2,"cmb":0,"cmd":18,"feats":[{"feat":"Dodge"},{"feat":"Mobility","type":"bonus"},{"feat":"Spring Attack","type":"bonus"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":14,"special":"+50 jump"},{"skill":"Bluff","value":9},{"skill":"Craft (any one)","value":9},{"skill":"Escape Artist","value":14},{"skill":"Knowledge (nature)","value":9},{"skill":"Perception","value":11},{"skill":"Stealth","value":18,"special":"+26 in natural surroundings"},{"skill":"Survival","value":6}],"languages":["Aklo","Common"],"sq":[{"type":"poison"}],"environments":["temperate forests"],"organizations":["gang (2-4)","band (4-11 plus 1 6-HD leader)"],"treasure":"no coins; 50% goods; 50% items","description_visual":"This creature looks like a small elf with large, pointed ears rising to points above its head. Its skin has a bluish tint and its hair is light. It is dressed in brightly colored clothing and wields a small, wicked-looking dagger.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Natural Invisibility","kind":"Su","details":"A quickling is invisible when motionless. It loses this invisibility and remains visible for 1 round in any round in which it takes any action other than a free action."},{"type":"Poison Use","kind":"Ex","details":"A quickling is never at risk of poisoning itself when handling poison. They usually use kava leaf poison on their daggers."},{"type":"Supernatural Speed","kind":"Su","details":"A quickling moves with incredible speed. Save for when it remains motionless (at which point it is invisible), a quickling's shape blurs and shimmers with this speed, granting it concealment (20% miss chance). In addition, this ability grants the quickling evasion and uncanny dodge (as the rogue abilities of the same name)."},{"type":"Slow Susceptibility","kind":"Ex","details":"A quickling that succumbs to a slow effect loses its supernatural speed ability and is sickened."}],"description":"Believed to be the offspring of an elf and a brownie (see that entry), the quickling is an evil faerie creature that hates all other races (especially the other fey races). How they came to be evil and malign is still a mystery, but legend speaks of the first quicklings as being great sorcerers. Elven scholars believe these quickling sorcerers unleashed some spark of the arcane that was never meant for mortal creatures.\n\nQuicklings resemble small elves with large ears that rise to points above their heads. Their skin is pale blue to blue-white and hair is either silver or white. They prefer clothes of bright and boisterous colors; reds, yellows, silvers, blacks, and blues are among their favorites. Quicklings never wear armor.\n\nQuicklings speak Common and Aklo. Both are spoken so quickly that even those able to speak one of the languages may still find it difficult to converse with a quickling.\n\nBecause of their rapid metabolism, quicklings reach adulthood by the age of 2, middle age at 5, old age at 12, and venerable at age 15.\n\nNo creature can match the natural speed and agility of a quickling. It knows this, and uses its great speed to its advantage in combat. A quickling often rushes an opponent, stabs it with its dagger, and then retreats out of melee range before an opponent can react.\n\nKava Leaf Poison: Type ingestion or injury; save DC 15; frequency 1/min. for 2 min.; effect sleep 1 hour; cure 1 save.","ecology":"","habitat_society":"","credit":"The Quickling originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission.","gear":"5 doses of kava leaf poison; Other Gear dagger"},{"name":"Raven Swarm","cr":3,"xp":800,"alignment":"N","size":"Tiny","type":"animal","subtypes":["swarm"],"init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 size, +0 natural","hp":18,"hd":"4d8","hdvalue":4,"fort":3,"ref":6,"will":3,"defensive_abilities":["half damage from piercing and slashing"],"immunities":["swarm traits"],"weaknesses":["swarm traits"],"speed":[{"type":"land","speed":10},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"swarm (1d6 plus eye-rake)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 11"},{"type":"eye-rake"}],"strength":2,"dexterity":15,"constitution":8,"intelligence":2,"wisdom":15,"charisma":7,"baseatk":3,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":10},{"skill":"Perception","value":11}],"environments":["temperate forests"],"organizations":["solitary","unkindness (2-4 swarms)","murder (5-10 swarms)"],"treasure":"none","description_visual":"A screeching cawing whirlwind of buffeting wings, clawing talons and pecking beaks.","group":"Raven","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Eye-Rake","kind":"Ex","details":"Any living creature damaged by a raven swarm must succeed on a DC 11 Reflex save or be blinded as the swarm scratches and tears at the victim's eyes. The blindness lasts for 1d4 days or until healed with a remove blindness or a successful DC 11 Heal check. The save DC is Constitution-based."}],"description":"A raven swarm is a disorienting mass of angered birds. Raven swarms have the same general characteristics and habitat of normal ravens.\n\nRaven swarms attack by surrounding their prey, pecking, scratching and clawing until destroyed or frightened away. They specifically seek the head, face and eyes of victims.","ecology":"","habitat_society":""},{"name":"Retch Hound","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"auras":["stench (DC 13, 10 rounds)"],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +5 natural","hp":22,"hd":"3d10+6","hdvalue":3,"fort":5,"ref":5,"will":2,"speed":[{"type":"land","speed":40}],"melee":"bite +5 (1d6+2 plus trip)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"10-ft. cone, 2d6 acid damage plus nauseated 1d3 rounds, Reflex DC13 for half and not nauseated, usable ever 8+1d4 rounds"}],"strength":14,"dexterity":15,"constitution":15,"intelligence":5,"wisdom":12,"charisma":4,"baseatk":3,"cmb":5,"cmd":17,"cmd_special":"+4 vs. Trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Track"}],"skills":[{"skill":"Perception","value":12},{"skill":"Survival","value":6,"special":"+10 scent tracking"}],"environments":["temperate forests","temperate marshes"],"organizations":["solitary","pair","pack (3-6)"],"treasure":"none","description_visual":"This large, muscular dog has sickly brownish-yellow fur, matted or torn in places. Small sores cover its body, each oozing a thick, yellowishgreen liquid. Its mouth is filled with long pointed yellow teeth, some broken off on the ends. Most disturbingly, it has four large yellow eyes evenly aligned across its canine head.","source":"Tome of Horrors Complete (3pp)","description":"Retch hounds are large, yellowish, sickly-looking hounds, about the size of war dogs. They are highly aggressive and powerfully built carnivores that love the taste of human flesh and bones. Their appearance lends to the façade of a sickly dog, which sometimes works to the retch hound's advantage when hunting its prey.\n\nRetch hounds are often found in the service of powerful fighters and warriors, who use the dogs to guard prisoners, lead hunting expeditions, and perform other such services. A retch hound is only as loyal to its master as it has to be to insure its own survival. While the dog won't necessary seek escape at the earliest possible time, it often turns on its master at some point. Retch hounds raised in captivity are often more loyal to their masters than those captured in the wild. A typical retch hound stands 4 to 4 1/2 ft. tall at the shoulder and weighs about 150 pounds.\n\nRetch hounds hunt their prey in packs. Using an eerie howl, they seem to coordinate and communicate with one another during these hunts. A favored tactic of a retch hound pack is to encircle a foe and then hit it from all sides at once. Usually the largest hound in the pack is the leader.\n\nWhen slain, a retch hound melts into a pile of stinking and bubbling slime.","ecology":"","habitat_society":""},{"name":"Sandman","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["elemental","extraplanar","earth"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["sleep aura (20 ft., DC 14)"],"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+1 Dex, +5 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":6,"ref":2,"will":4,"defensive_abilities":["protection from arrows"],"immunities":["elemental traits"],"sr":15,"speed":[{"type":"land","speed":30}],"melee":"slam +7 (1d4+3 plus sleep)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":12,"constitution":14,"intelligence":10,"wisdom":11,"charisma":14,"baseatk":4,"cmb":6,"cmd":17,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Knowledge (arcana)","value":7},{"skill":"Knowledge (planes)","value":7},{"skill":"Perception","value":7},{"skill":"Sense Motive","value":7},{"skill":"Stealth","value":8},{"skill":"Use Magic Device","value":9}],"languages":["Terran"],"environments":["any (Elemental Plane of Earth)"],"organizations":["solitary","gang (2-4)"],"treasure":"double coins, standard goods, standard items","description_visual":"This creature appears as a slender, lithe humanoid constructed of sand.  Delicate features can be seen on its face, and its fingers are long and slender.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Sleep","kind":"Su","details":"A creature struck by a sandman must succeed on a DC 14 Will save or be affected as though by a sleep spell (caster level 8th). There is no limit to the number of Hit Dice a sandman can affect with this aura. The save DC is Charisma-based. Creatures attacking a sandman unarmed or with natural attacks are also subject to this special attack."},{"type":"Sleep Aura","kind":"Su","details":"A sandman can radiate a 20-foot-radius sleep aura as a free action. A creature in the area must succeed on a DC 14 Will save or be affected as though by a sleep spell (caster level 8th). There is no limit to the number of Hit Dice a sandman can affect with this aura. A creature that successfully saves cannot be affected again by the same sandman's sleep aura for one day. The save DC is Charisma-based."},{"type":"Protection from Arrows","kind":"Su","details":"A sandman is protected by a permanent protection from arrows effect (as the spell) that grants it damage reduction 10/magic against ranged weapons. This ability is inherent and cannot be dispelled."}],"description":"Sandmen are silicate creatures from the Elemental Plane of Earth.\n\nTheir purpose on the Material Plane is unknown, but spellcasters often summon them when they want to protect someone or something. Though sandmen have evil tendencies many willingly serve summoners of other alignments. Sandmen have an immense dislike for humans (reasons unknown) and attack them on sight-human spellcasters take heed when employing their services! A sandman attacks its opponent by pummeling it with its fists, though it prefers to avoid combat if possible. Given the chance, a sandman attempts to put an opponent to sleep rather than kill it. A sleeping creature is left to its own devices; a sandman doesn't further attack a creature it puts to sleep. Sleeping creatures are often carried to the sandman's master where they are enslaved or worse.","ecology":"","habitat_society":"","credit":"The Sandman originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Sewer Sludge","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"ooze","subtypes":["aquatic"],"init":0,"senses":[{"type":"blindsight","modifier":"30 ft."}],"auras":["stench (10 ft., DC 17)"],"ac":14,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+4 natural","hp":38,"hd":"4d8+20","hdvalue":4,"fort":6,"ref":1,"will":-4,"immunities":["cold","electricity","ooze traits"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20},{"type":"swim","speed":20}],"melee":"slam +6 (1d8+4 plus disease and grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d8+4"}],"strength":16,"dexterity":10,"constitution":20,"wisdom":1,"charisma":1,"baseatk":3,"cmb":6,"cmb_special":"+4 vs. grapple","cmd":16,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":11},{"skill":"Swim","value":11}],"sq":[{"type":"amphibious"},{"type":"camouflage"}],"environments":["any"],"organizations":["solitary","smattering (2-5)"],"treasure":"none","description_visual":"Suddenly, the pile of sewage rises up and extends a long brown pseudopod dripping with vulgar fluids.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Camouflage","kind":"Ex","details":"Since a sewer sludge looks like normal sludge when at rest, a DC 20 Perception check is required to notice it before it attacks for the first time. Anyone with ranks in Survival or Knowledge (dungeoneering) can use either of those skills instead of Perception to notice the ooze."},{"type":"Cold Immunity","kind":"Ex","details":"A sewer sludge hit by a cold-based attack takes no damage. However, if the amount of damage it would have otherwise taken exceeds its Constitution score, the sewer sludge is slowed (as the slow spell) for 1d6 rounds."},{"type":"Disease","kind":"Ex","details":"Filth fever: Slam-contact; save DC 17 Fort; onset 1d3 days; frequency 1/day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Stench Aura","kind":"Ex","details":"Creatures entering the area must succeed on a DC 17 Fortitude save or be sickened for as long as they remain in the area and for 1d4 rounds after leaving it. The save DC is Constitution-based."}],"description":"A sewer sludge is a disgusting ooze that resembles nothing more than a filthy pile of sewage. They lurk in the sewer and waste-water systems of large cities, usually content to feed on rats and refuse that filters down from the streets overhead.\n\nA sewer sludge is a globular mass about 4 ft. across, and weighing 100 pounds.\n\nSewer sludges are almost always hungry, and don't hesitate to attack prey larger than themselves. A sewer sludge's usual method of attack is to glom onto the body of a creature struck by its pseudopod, grip it tightly, and liquefy its flesh by releasing acidic digestive enzymes.\n\nSpawn of Dungie\n\nThe origin of sewer sludges was unknown until recently. Diligent research by a curious adventurer named Bilark Weterson finally tracked down where these creatures came from, and the news was not good at all. Weterson realized that sewer sludges first appeared in cities often frequented by travelers returning from a certain famous dungeon. Following a hunch, he investigated and was never heard from again. Weterson's diary was recently uncovered in a used book store in Bard's Gate, and in it were discovered his theories about sewer sludges.\n\nIt is known that in the upper levels of the dungeon known as Rappan Athuk there exists a creature called the Dung Monster. The good news is that the Dung Monster, nicknamed ‘Dungie' by those few who have survived an encounter with that it, is content to remain in Rappan Athuk and not venture into the outside world. The bad news is that Dungie has begun to reproduce.\n\nOnce every few years, Dungie grows odd nodules on its surface. These nodules continue to bud until they fall away and take on a life of their own. Sometimes, a bud finds its way outside of Rappan Athuk, either on its own or hidden in the packs and clothing of weary adventurers as they exit the dungeon. If undetected, these buds drop out into the sewers of the great cities of the world and grow into sewer sludges. Fortunately, sewer sludges remain mindless oozes as they age. Were they to mature into adhesive, shape-changing, immortal monsters like their progenitor, the world might surely be doomed!","ecology":"","habitat_society":""},{"name":"Shadow Wolf","cr":3,"xp":800,"alignment":"CE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 deflection, +2 Dex","hp":26,"hd":"4d8+8","hdvalue":4,"fort":3,"ref":3,"will":5,"defensive_abilities":["incorporeal","shadow blend"],"immunities":["undead traits"],"speed":[{"type":"land","speed":50}],"melee":"incorporeal bite +5 (1d4 Str)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"trip","details":"bite"}],"dexterity":15,"intelligence":4,"wisdom":12,"charisma":15,"baseatk":3,"cmb":5,"cmd":17,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Perception","value":9},{"skill":"Sense Motive","value":3},{"skill":"Survival","value":2,"special":"+6 tracking by scent"}],"environments":["any"],"organizations":["solitary","pair","pack (5-12)"],"treasure":"none","description_visual":"This creature appears as a large black hound formed of darkness. Its eyes burn with a crimson fire.","group":"Wolf","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Strength Damage","kind":"Su","details":"The bite of a shadow wolf deals 1d4 points of Strength damage to a living foe. A creature reduced to Strength 0 dies."},{"type":"Trip","kind":"Ex","details":"A shadow wolf can assume a corporeal form as a free action and bite (as a standard action) a foe in an attempt to trip the opponent. A shadow wolf that hits with its bite attack can attempt to trip the opponent as a free action without making a touch attack or provoking an attack of opportunity. If the attempt fails, the opponent cannot react to trip the shadow wolf. Shadow wolves use their Dexterity modifier on trip attacks. The shadow wolf remains corporeal (i.e., it loses its incorporeal traits) for the entire round in which it attempts to trip an opponent. It can assume its incorporeal form on its next turn as a free action."},{"type":"Shadow Blend","kind":"Ex","details":"In any condition of illumination other than full daylight, a shadow wolf can disappear into the shadows, giving it total concealment. Artificial illumination, even a light or continual flame spell, doesn't negate this ability; a daylight spell, however, will."}],"description":"Shadow wolves are nocturnal hunters and hate all living creatures. Their eyes flash with a crimson fire when prey is sighted. Shadow wolves prefer to attack from ambush, using the shadows and darkness to their advantage. When prey wanders nearby, a shadow wolf leaps to the attack. A shadow wolf pack leads its prey into an ambush and then strikes when opponents are completely unaware.","ecology":"","habitat_society":""},{"name":"Sheet Fungus","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"plant","subtypes":["fungus"],"init":3,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+3 Dex, +4 natural","hp":25,"hd":"3d8+12","hdvalue":3,"fort":7,"ref":4,"will":3,"dr":"5/bludgeoning","immunities":["plant traits"],"speed":[{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"slam +4 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"engulf","details":"1d6+3"}],"strength":14,"dexterity":16,"constitution":18,"intelligence":10,"wisdom":11,"charisma":10,"baseatk":2,"cmb":4,"cmd":17,"cmd_special":"can't be tripped","feats":[{"feat":"Hover"},{"feat":"Iron Will"}],"skills":[{"skill":"Fly","value":11},{"skill":"Perception","value":6},{"skill":"Stealth","value":8}],"languages":["Common","Sylvan (cannot speak)"],"sq":[{"type":"camouflage"}],"environments":["any"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"What at first appeared to be an intricately carved tapestry is apparently alive as it springs at you.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Camouflage","kind":"Ex","details":"A sheet fungus can hold itself completely still and resembles a rug or wall hanging. It takes a successful DC 20 Perception check to notice a sheet fungus before it attacks."},{"type":"Engulf","kind":"Ex","details":"A sheet fungus can try to wrap a creature of its size or smaller in its body as a standard action. The sheet fungus attempts a grapple check that doesn't provoke an attack of opportunity. If it wins the grapple check, it establishes a hold and squeezes the engulfed prey dealing automatic slam damage each round the grapple is held. Attacks that hit an engulfing sheet fungus deal half of their damage to the monster and half to the trapped victim."}],"description":"Sheet funguses are flat, sheet-like plant creatures believed to be created by evil priests who experimented with various plants and funguses mixed with dark magic. They resemble tapestries or rugs and use this to their advantage when hunting for food. Sheet funguses are fond of blood and flesh, especially that of humans. Sheet funguses are sometimes found acting as guards in temples dedicated to foul fungus and ooze demons.\n\nA sheet fungus is a flat, sheet thin creature about 6 ft. long and 2-1/2 or 3 ft. wide. It weighs about 3 pounds. Two small dark circles \"sewn\" into its design function as eyes.\n\nSheet funguses press themselves up against walls or floors so as to appear to be nothing more than a wall hanging or rug. When a potential meal wanders too close, the sheet fungus springs out and attempts to envelope the target in its body. A grabbed opponent is held until it dies or until the sheet fungus takes 3/4 or more of its hit points in damage at which time it usually releases its prey and flees. A hungry sheet fungus will fight to the death however. There is a 5% chance that any creature slain by a sheet fungus returns to life as a free-willed vegepygmy.","ecology":"","habitat_society":""},{"name":"Sirine Flower","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"plant","init":4,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":10,"ac_flat_footed":15,"ac_mods":"+5 natural","hp":32,"hd":"5d8+10","hdvalue":5,"fort":8,"ref":1,"will":2,"immunities":["plant traits"],"resists":[{"type":"fire","value":5}],"speed":[{"type":"land","speed":10}],"melee":"4 tendrils +6 (1d4+2 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"charming song"},{"type":"essence drain"}],"strength":14,"dexterity":10,"constitution":14,"intelligence":10,"wisdom":12,"charisma":14,"baseatk":3,"cmb":5,"cmb_special":"+4 vs. grapple","cmd":15,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Weapon Focus (tendril)"}],"skills":[{"skill":"Perception","value":9},{"skill":"Stealth","value":8,"special":"+18 in undergrowth"}],"languages":["Common (cannot speak)"],"environments":["temperate forests","temperate marshes"],"organizations":["solitary","pair","grove (3-5)"],"treasure":"incidental","description_visual":"This creature appears as an animated plant with a flowering base and several writhing stalks each topped with flowers of red, amber, gold, silver, bronze, and purple.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Charming Song","kind":"Su","details":"Sirine flowers emit a soothing and tranquil humming in a 60-foot radius that resembles music or birds singing. Those hearing the song must succeed on a DC 16 Will save or become captivated by the sound. A creature that successfully saves isn't subject to the same sirine flower's song for one day. A victim under the effects of this ability moves toward the sirine flower using the most direct means available. If the path leads them into a dangerous area such as through fire or off a cliff, that creature receives a second saving throw to end the effect before moving into peril. Captivated creatures can take no actions other than to defend themselves. A victim within 5 ft. of the sirine flower simply stands and offers no resistance to the sirine flower's attacks. This effect continues for as long as the sirine flower sings and for 1 round thereafter. This is a sonic mind-affecting charm effect. The save DC is Charisma-based and includes a +2 bonus."},{"type":"Essence Drain","kind":"Su","details":"A grabbed creature takes normal damage plus 1d2 points of Intelligence damage each round until it escapes."}],"description":"Sirine flowers are sentient, slow-moving, flesh-eating, 5-foot tall flowers with many thick stalks and leaves. The flower emits a pleasant odor noticeable to a range of 30 ft. They are most often found in dense forests near other plants where they sit waiting for prey to move within range. Typical prey for a sirine flower includes small birds, rodents, and other such creatures. Such creatures supply the sirine flower with sustenance for a time, but in order to gain the nutrients it needs to sustain it, the sirine flower must kill an intelligent creature and feed on its essence.\n\nThe sirine flower typically stands about 5 ft. tall from base to the tip of its stalks. They can grow to a height of nearly 10 ft., though flowers this large are uncommon at best. The base of a sirine flower is a thick, leathery, brown-colored sac about 2 ft. in diameter, located just beneath the surface of the ground. Strong, thick roots grow in all directions from the base, reaching lengths of 5 to 6 ft. Above ground, a thick clump of leaves grows from the base of the plant. From these leaves a series of 6 to 10 stalks reach upward. Each stalk is thick, slightly coarse and leathery to the touch with many small leaves and flowers growing from it. Flowers are red, amber, gold, silver, bronze, purple, or gray. Hidden among the base leaves and stalks are the creature's four tendrils which it uses to ensnare its prey. The tendrils, like the stalks, are grayish-brown in color.\n\nThe sirine flower begins combat using its charm ability to lure its prey in where it can attack with its tendrils. Once an opponent is within range, it lashes out, attempting to grab the foe with its tendrils. A grabbed opponent is held and drained of its Intelligence until it escapes, is slain, or rendered unconscious (and helpless). Unconscious foes are slain and devoured by the sirine flower's roots but only if all other attackers have been slain, rendered unconscious, or fled. If the sirine flower still faces aggressors, it turns its attention to them. Only when all are defeated or fled, does the sirine flower digest its meal.","ecology":"","habitat_society":""},{"name":"Skitterdark Demon","cr":3,"xp":800,"alignment":"CE","size":"Tiny","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":16,"ac_flat_footed":15,"ac_mods":"+3 Dex, +1 dodge, +3 natural, +2 size","hp":34,"hd":"4d10+12","hdvalue":4,"fort":7,"ref":4,"will":5,"dr":"5/cold iron","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":14,"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"2 claws +9 (1d3-1), bite +9 (1d4-1)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"profane claws"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"1/day","spells":[{"spell":"hold person"},{"spell":"scare"}]}],"strength":8,"dexterity":17,"constitution":16,"intelligence":11,"wisdom":12,"charisma":12,"baseatk":4,"cmb":5,"cmd":15,"feats":[{"feat":"Dodge"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Escape Artist","value":10},{"skill":"Fly","value":18},{"skill":"Perception","value":8},{"skill":"Stealth","value":18},{"skill":"Survival","value":8}],"languages":["Abyssal","Common"],"sq":[{"type":"clustering"}],"environments":["any (Abyss)"],"organizations":["gang (3-6)","roving band (7-10)","swarm (11-16)"],"treasure":"half standard","description_visual":"A small humanoid-shaped creature no more than 1-foot tall flutters nearby, held aloft by its crimson leathery bat wings. Its body is blood red and somewhat stocky for its size. Its hands end in sharp claws and its eyes and teeth are sickly yellow.","group":"Demon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Clustering","kind":"Ex","details":"Because of their small size and swarming tactics, up to 4 skitterdarks can fit in the same 5-foot space and function normally."},{"type":"Profane Claws","kind":"Su","details":"Any good-aligned creature hit by a skitterdark's claw attack takes normal damage plus 1d6 points of profane damage."}],"description":"Skitterdarks are tiny demons that relish in the destruction of others, especially good-aligned outsiders (in this case outsiders mean those not native to the Abyss). Not normally found in large numbers within the rank-and-file of demonic armies, some lords do employ these creatures as watch patrols around their palaces or along their borders. What these creatures lack in size and strength, they make up for in ferocity and determination.\n\nSkitterdarks roam their home planes harassing other demons and creatures not native to their Abyssal planes. They have a fondness for the flesh of mortals, particularly goblins and halflings, often capturing the latter and cooking it over a slow-burning fire using an iron spit. Some skitterdarks wear the flayed skin of goblins and halflings as trophies, weaving arm bands, bracelets, or necklaces from the dried out flesh.\n\nSkitterdarks stand 1 foot tall and weigh about 15 pounds. Its wings are crimson, its body red, and its claws blackened and usually filthy.\n\nSkitterdarks are aggressive demons that attack using their tiny sickles or claws and bite. They rarely touch the ground during combat, preferring to attack from the air. Against good-aligned creatures they always forego weapons so they can use their profane claws. When encountered in great numbers, skitterdarks form clusters and swarm over their opponents, raking with their claws or slashing with their tiny weapons. Some skitterdarks carry poisons extracted from various abyssal plants in order to coat their weapons.","ecology":"","habitat_society":""},{"name":"Skulleton","cr":3,"xp":800,"alignment":"NE","size":"Tiny","type":"undead","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+2 natural, +2 size","hp":26,"hd":"4d8+8","hdvalue":4,"fort":3,"ref":1,"will":5,"immunities":["undead traits"],"speed":[{"type":"fly","speed":10,"maneuverability":"perfect"}],"melee":"bite +5 (1d3-2 plus disease)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"dust"}],"strength":6,"dexterity":10,"intelligence":10,"wisdom":12,"charisma":14,"baseatk":3,"cmb":1,"cmd":9,"cmd_special":"can't be tripped","feats":[{"feat":"Dazzling Display"},{"feat":"Weapon Finesse","type":"bonus"},{"feat":"Skill Focus (Intimidate)","type":"bonus"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Fly","value":19},{"skill":"Intimidate","value":12},{"skill":"Perception","value":11},{"skill":"Stealth","value":16}],"languages":["Common (cannot speak)"],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard","description_visual":"This being looks like a humanoid skull with several small gems inset in its eye sockets and mouth.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Disease","kind":"Ex","details":"Filth fever: Bite-injury; save Fort DC 12; onset 1d3 days; frequency 1/day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves."},{"type":"Dust","kind":"Ex","details":"The skulleton can use its crumbled remains to attack any creature that comes within 10 ft. Twice per day as a standard action, it can billow forth a cloud of dust that surrounds it in a 10-foot radius. Creatures caught within the area must succeed on a DC 14 Fortitude save or be nauseated for 6 rounds. The dust cloud remains for 2 rounds and can be affected by wind. The save DC is Charisma-based."}],"description":"Skulletons are undead creatures believed to have been created by a lich or demilich, for the creature greatly resembles the latter in that it isn'thing more than a pile of dust, a skull, and a collection of bones.\n\nThe gemstones inset in its eye sockets and in place of its teeth are not gemstones at all, but painted glass (worthless). The skulleton is thought to have been created to frighten off would-be tomb plunderers, or convince them they have defeated the skulleton's creator rather than a minor servitor and tomb guardian.\n\nA skulleton lies in wait for its prey. When a living creature touches a skulleton, it uses its dust attack to incapacitate and confuse the intruders.\n\nThen it rises in the air, pivoting to face its prey and glowering in a display of fearsome presence, using its Dazzling Display feat as a full-round action to attempt to demoralize those near it. If the intruders have not fled, it moves in to bite with its gem-encrusted teeth.\n\nConstruction A skulleton's body consists of a humanoid skull and the bones and dusty remains of its body. The false jewels are worthless, but do require a jeweler of some skill to properly cut and mount them to lend them an air of authenticity. Additional rare powders and incense worth 3,500 gp are also needed to complete the process.\n\nSKULLETON CL 9th; Price 8,000 gp Requirements animate dead, contagion, fly, stinking cloud, creator must be caster level 9th; Skill Craft (jeweler) DC 15; Cost 4,000 gp","ecology":"","habitat_society":""},{"name":"Slime Mold","cr":3,"xp":800,"alignment":"N","size":"Large","type":"ooze","subtypes":["fungus"],"init":-1,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":8,"ac_touch":8,"ac_flat_footed":8,"ac_mods":"-1 Dex, -1 size, +0 natural","hp":38,"hd":"4d8+20","hdvalue":4,"fort":6,"ref":0,"will":-4,"immunities":["ooze traits"],"speed":[{"type":"land","speed":20}],"melee":"slam +3 (1d8+1 plus disease plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"engulf","details":"1d8+1"}],"strength":13,"dexterity":8,"constitution":21,"wisdom":1,"charisma":1,"baseatk":3,"cmb":5,"cmb_special":"+4 vs. grapple","cmd":14,"cmd_special":"can't be tripped","sq":[{"type":"camouflage"}],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"none","description_visual":"A large but colorful grove of small mushrooms and other tiny plants sprout upon a wide swath of moss.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Camouflage","kind":"Ex","details":"A slime mold looks like a normal patch of fungus when at rest. It takes a DC 20 Perception check to notice it before it attacks. Anyone with ranks in Survival or Knowledge (nature) can use one of those skills instead of Perception to notice the ooze. Dwarves can use stonecunning to notice the subterranean version."},{"type":"Disease","kind":"Ex","details":"Fungal rot: Slam-contact; save Fort DC 17; onset 1 day; effect 1d3 Con and 1d3 Str damage; cure 1 save. The save DC is Constitution-based."},{"type":"Engulf","kind":"Ex","details":"A slime mold can wrap a creature of up to one size smaller in its body as a standard action. If a slime mold succeeds a Combat Maneuver check to grapple an opponent, it establishes a hold and deals slam damage each round the hold is maintained. Attacks that hit an engulfing slime mold deal half their damage to the monster and half to the trapped victim."}],"description":"Slime molds are found in forests, swamps, and underground; any place natural fungi and mold grows. A slime mold lies dormant among the growths soaking nutrients from them, and waiting for living creatures to wander too close to it.\n\nSlime molds are often mistaken for plant creatures because their forms are completely covered with molds, fungi, and in particular mushrooms of varying hues, shapes, and sizes. This gives the monster the appearance of an undulating mass of plant matter when actuality they are a rare form of non-acidic ooze. Something in the creature's protoplasmic substance causes mushrooms, molds, mosses, and other fungal plants to take root and grow on its surface in a symbiotic relationship.\n\nA slime mold attacks from surprise anytime it detects a living creature within 10 ft. of it. It lashes out with a pseudopod and then attempts to wrap its body around the victim. The slime mold relies on its natural ability to appear as a patch of mushrooms to foil potential prey. Slime molds inflict an opponent with fungal rot if they hit with a slam attack.\n\nFungal rot causes a darkening of the skin and small patches of fungus and mold to sprout at random locations on the victim's body.","ecology":"","habitat_society":""},{"name":"Slithering Tracker","cr":3,"xp":800,"alignment":"N","size":"Small","type":"ooze","init":4,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+4 natural, +1 size","hp":47,"hd":"5d8+25","hdvalue":5,"fort":6,"ref":1,"will":1,"defensive_abilities":["sealed mind","transparent"],"immunities":["ooze traits"],"speed":[{"type":"land","speed":10},{"type":"climb","speed":10}],"melee":"slam +6 (1d4+3 plus paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"engulf","details":"paralysis and plasma drain"},{"type":"paralysis","details":"1d4 hours, DC 17, also when struck by unarmed attacks or natural weapons"},{"type":"plasma drain"}],"strength":14,"dexterity":10,"constitution":21,"intelligence":10,"wisdom":10,"charisma":1,"baseatk":3,"cmb":5,"cmb_special":"+4 vs. grapple","cmd":19,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":8},{"skill":"Stealth","value":16}],"environments":["any underground"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature looks like a long, thin transparent protoplasm, almost snake-like in form.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Engulf","kind":"Ex","details":"A slithering tracker can engulf a paralyzed foe up to one size larger than itself as a standard action. It cannot make a slam attack during a round in which it engulfs. The slithering tracker merely has to move into a space occupied by a paralyzed creature, completely covering it. An engulfed opponent is subjected to the slithering tracker's paralysis and plasma drain, and is considered to be grappled and trapped within its body. A slithering tracker only uses this ability against a paralyzed, sleeping, or otherwise helpless opponent."},{"type":"Plasma Drain","kind":"Ex","details":"A slithering tracker drains the body fluids from an engulfed opponent. Each 5 minutes an opponent is engulfed, it takes 1 point of Constitution damage. Because it takes a long time to completely drain a foe, a slithering tracker generally only uses this ability against a paralyzed, stunned, held, or sleeping opponent."},{"type":"Sealed Mind","kind":"Ex","details":"Even though a slithering tracker has an Intelligence score, it is immune to all mind-affecting effects (charms, compulsions, phantasms, patterns, and morale effects) just as other oozes are."},{"type":"Transparent","kind":"Ex","details":"A slithering tracker is hard to identify, even under ideal conditions, and it takes a DC 15 Perception check to notice one. Creatures who fail to notice a slithering tracker and walk into it are automatically hit with a slam attack and subjected to the creature's paralysis attack."}],"description":"The slithering tracker is an amorphous and transparent creature that inhabits dark underground areas of the world. Unlike other oozes, the slithering tracker doesn't feed on organic matter. It survives by devouring living creatures. A typical slithering tracker is 3 ft. long and has a thickness of about 6 inches. It can grow to a length of about 8 ft. A slithering tracker prefers to attack helpless or immobile opponents. Once it paralyzes an opponent, the slithering tracker flows over it and drains its body fluids. The tracker, now sated, slithers off to digest its meal. All that's left of the opponent is a dry and rotted husk.","ecology":"","habitat_society":"","credit":"The Slithering Tracker originally appeared in the Strategic Review #5 (© TSR/Wizards of the Coast, 1975) and later in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission."},{"name":"Slitherrat","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"animal","init":3,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+3 Dex, +1 natural","hp":25,"hd":"4d8+4","hdvalue":4,"fort":5,"ref":7,"will":2,"speed":[{"type":"land","speed":30},{"type":"burrow","speed":30}],"melee":"bite +6 (1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"diamond teeth"}],"strength":10,"dexterity":17,"constitution":13,"intelligence":2,"wisdom":13,"charisma":4,"baseatk":3,"cmb":3,"cmd":16,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":8},{"skill":"Perception","value":4},{"skill":"Stealth","value":8}],"sq":[{"type":"pass through crystal"}],"environments":["any underground"],"organizations":["solitary","cache (2-12)"],"treasure":"none","description_visual":"These rodents have a long three to four foot long snakelike body covered in fur, with four almost vestigial legs on each side. The long body tapers into a rat-like tail at the end, adding another foot to the creature's overall length. The head, although large, is clearly that of a giant rat; but the long front teeth glitter, for they are made of thin, sharp diamond.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Diamond Teeth","kind":"Ex","details":"Because the teeth are so hard and sharp, a slitherrat's bite attack bypasses all hardness and deals 1d6+1 damage."},{"type":"Pass Through Crystal","kind":"Ex","details":"Slitherrats may pass through crystal and similar gemstone-like materials as if they were not even present, leaving no trace of their passage."}],"description":"Slitherrats are a bizarre variant of the giant rat, sometimes found in places with heavy crystalline mineral deposits. These strange creatures use their teeth to dig through earth and solid rock when they encounter such obstacles.","ecology":"","habitat_society":"","credit":"Original author Matthew J. Finch  Originally appearing in The Spire of Iron and Crystal (© Frog God Games/Matthew J. Finch, 2011)"},{"name":"Sloth Viper","cr":3,"xp":800,"alignment":"N","size":"Large","type":"magical beast","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision","modifier":"null"}],"ac":17,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+4 Dex, +4 natural, -1 size","hp":27,"hd":"5d10","hdvalue":5,"fort":4,"ref":8,"will":2,"speed":[{"type":"land","speed":30},{"type":"climb","speed":30},{"type":"swim","speed":30}],"melee":"bite +8 (1d4+1 plus poison)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"quickness"}],"strength":13,"dexterity":19,"constitution":11,"intelligence":2,"wisdom":12,"charisma":2,"baseatk":5,"cmb":7,"cmd":21,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":16},{"skill":"Climb","value":13},{"skill":"Perception","value":9},{"skill":"Stealth","value":8},{"skill":"Swim","value":15}],"environments":["any marshes","temperate forests","warm forests"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This large emerald snake has bands of gold and black ringing its body and a black-tipped tail.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save DC 14; frequency 1 round/6 rounds; effect slowed for 1 minute as the slow spell (CL 7th); cure 2 consecutive saves. The save DC is Constitution-based and includes a +2 racial bonus."},{"type":"Quickness","kind":"Ex","details":"A sloth viper is inherently quick and can take an extra standard action or move action during its turn each round."}],"description":"The sloth viper is a lightning-quick predator most often found in dense, thick jungles or overgrown swamplands. The typical sloth viper is 9-10 ft. long, though they can grow to a length of 20 or more ft. They subsist on a diet of small animals, preferring birds, lizards, and small mammals to others. They are fearless however, and don't hesitate to attack much larger prey such as cheetahs, leopards, and even lions. Once the sloth viper has fed, it often recoils high above the ground, under the thicket and blanket of leaves, branches, and limbs where it sleeps for the next 1d6 days.\n\nThe sloth viper is a solitary predator; rarely is more than one encountered.\n\nIf such an encounter takes place, they are often a mated pair, with a nest of eggs nearby. A sloth viper's lair is a dense thicket of natural underbrush and trees. A typical nest contains 1d4 emerald colored eggs.\n\nSloth vipers are hunted by some humanoids for their scales and poison (which is rumored to be valued by spellcasters for its properties).\n\nSloth vipers are ambush hunters and wait patiently among the limbs and branches of trees for potential prey to pass underneath it. When unsuspecting prey is in range, the viper either drops on it from above, or snaps down quickly with its vicious bite, recoiling back into the trees afterwards.","ecology":"","habitat_society":""},{"name":"Small Lightning Quasi-elemental","cr":3,"xp":800,"alignment":"N","size":"Small","type":"outsider","subtypes":["air","electricity","elemental","extraplanar"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["globe (5 ft., Ref DC 13, 1d6 electricity)"],"ac":19,"ac_touch":16,"ac_flat_footed":14,"ac_mods":"+4 Dex, +1 dodge, +3 natural, +1 size","hp":33,"hd":"6d10","hdvalue":6,"fort":2,"ref":9,"will":5,"dr":"5/-","immunities":["electricity","elemental traits"],"resists":[{"type":"acid","value":10},{"type":"fire","value":10}],"weaknesses":["vulnerability to water"],"speed":[{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"2 slams +9 (1d6 electricity)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"electricity"}],"strength":10,"dexterity":18,"constitution":10,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":6,"cmb":5,"cmd":20,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":23},{"skill":"Perception","value":9},{"skill":"Stealth","value":17}],"languages":["Auran"],"environments":["any (Quasi-Plane of Lightning)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature appears as a bluish globe of electrical energy. Lightning plays off and around its body.","group":"Quasi-elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Electricity","kind":"Ex","details":"A lightning quasi-elemental is composed entirely of electricity and deals electricity damage each time it hits. A creature striking the lightning quasi-elemental unarmed, or a creature striking the lightning quasi-elemental with a weapon take this same electricity damage each time one of their attacks hits. Metallic creatures or creatures using metal weapons take an extra 1d6 points of electricity damage each time one of their attacks hits."},{"type":"Globe","kind":"Ex","details":"As a standard action, a lightning quasi-elemental can discharge one globe of electricity per HD it possesses once per round. Globes hover by the quasi-elemental and move with the creature. An opponent that moves within 5 ft. of a lightning quasi-elemental discharges a globe and takes the electricity damage shown on the table below. An affected creature can make a Reflex save to reduce the damage by half. The save DC is Constitution-based. Once a globe discharges, it is destroyed and a lightning quasi-elemental cannot recreate it for 4 hours."},{"type":"Vulnerability to Water","kind":"Ex","details":"A lightning quasi-elemental takes 1d8 points of damage per gallon of water it contacts. Pouring water onto a lightning quasi-elemental requires a successful ranged touch attack. Water from other sources, such as spells or effects that create water but don't specify an amount in gallons, deal 1d4 points of damage per caster level to a lightning quasi-elemental within its area of effect. Damage from water-based attacks, like the slam attack of a water elemental, is increased by 50% against a lightning quasi-elemental."}],"description":"Lightning quasi-elementals are native to the Plane of Air, the Positive Energy Plane, and a rumored elemental plane situated in between (the Quasi-Plane of Lightning). They are sometimes summoned to the Material Plane by wizards or clerics, but more often than not slip through a rift between the Material Plane and elemental plane during a lightning storm. A lightning quasi-elemental can release small globes of electricity that hover around its body. An opponent that moves within 5 ft. of a globe causes it to arc and discharge.","ecology":"","habitat_society":"","credit":"The Lightning Quasi-elemental originally appeared in the First Edition module EX2 The Land Beyond the Magic Mirror (© TSR/Wizards of the Coast, 1983) and later in the First Edition Monster Manual II (© TSR/ Wizards of the Coast, 1983) and is used by permission."},{"name":"Smoke Mephit","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["air","extraplanar","fire"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+1 size, +2 Dex, +1 dodge, +3 natural","hp":16,"hd":"3d10","hdvalue":3,"hp_mods":["fast healing 2"],"fort":1,"ref":5,"will":3,"dr":"5/magic","immunities":["fire","outsider traits"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"perfect"}],"melee":"2 claw +3 (1d3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"15-foot cone of black soot, DC 12 for half, 1d4 fire"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"1/hour","spells":[{"spell":"blur"}]},{"frequency":"1/day","spells":[{"spell":"ember storm"},{"spell":"summon","details":"level 2, 1 smoke mephit 25%"}]}],"strength":10,"dexterity":14,"constitution":10,"intelligence":6,"wisdom":11,"charisma":15,"baseatk":3,"cmb":3,"cmd":17,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Bluff","value":7},{"skill":"Diplomacy","value":7},{"skill":"Disguise","value":6},{"skill":"Escape Artist","value":8},{"skill":"Fly","value":12},{"skill":"Intimidate","value":6},{"skill":"Perception","value":4},{"skill":"Stealth","value":8}],"languages":["Ignan","Common"],"environments":["any (Plane of Fire)"],"organizations":["solitary","gang (2-4)","mob (5-12)"],"treasure":"standard","description_visual":"This small winged humanoid has soot-colored skin, crimson eyes, and dark wings. Small trails of smoke stream from its body as it flies along.","group":"Mephit","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Ember Storm","kind":"Sp","details":"Once per day a smoke mephit can create a downpour of white-hot embers that affects a 20- foot radius. Living creatures caught in the storm take 2d6 points of fire damage (Reflex DC 14 half, caster level 6th). This ability is the equivalent of a 2nd-level spell. The save DC is Charisma-based."},{"type":"Fast Healing","kind":"Ex","details":"A smoke mephit heals only if it is exposed to smoke or soot (whether magically created or mundane in nature)."},{"type":"Sooty Breath","kind":"Su","details":"Living creatures that fail their saves against the smoke mephit's breath weapon are tormented by burning eyes. This effect imposes a -4 penalty to AC and a -2 penalty on attack rolls for 3 rounds. The save DC is Constitution-based and includes a +1 racial bonus."}],"description":"Smoke mephits are generally only encountered on the Plane of Molten Skies, though it is believed they originate from a plane or para-plane comprised entirely of smoke. They are generally lazy, but quick to anger.\n\nWhen encountered on the material planes it is usually because they have been summoned or called by a spellcaster to perform some task or chore.\n\nOn such planes, smoke mephits generally prefer warmer climates and are never found in cold areas (unless specifically called by a spellcaster).\n\nSmoke mephits enjoy combat and rush headlong into it, slashing with their claws. If a smoke mephit can draw its opponents to within 20 ft. of its position, it uses its spell-like abilities to create an ember storm.\n\nA smoke mephit's natural weapons are treated as magic weapons for the purpose of overcoming damage reduction. A smoke mephit stands about 4 ft. tall and weighs about 2 pounds.","ecology":"","habitat_society":""},{"name":"Snow Leopard","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"animal","init":4,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+4 Dex, +1 natural","hp":30,"hd":"4d8+12","hdvalue":4,"fort":6,"ref":8,"will":2,"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"2 claw +7 (1d4+2), bite +7 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +7, 1d4+2"}],"strength":15,"dexterity":19,"constitution":15,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":3,"cmb":5,"cmd":19,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Toughness","type":"bonus"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":4,"special":"+12 balancing"},{"skill":"Climb","value":10},{"skill":"Perception","value":10},{"skill":"Stealth","value":12}],"sq":[{"type":"snow move"}],"environments":["cold forests","cold mountains"],"organizations":["solitary","pair","den (1-2 adults plus 1-4 cubs)"],"treasure":"none","description_visual":"Grayish fur covers this large cat that allows it to blend in with the shadow and light of snow drifts.","group":"Leopard","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Snow Move","kind":"Ex","details":"Because of its large, fur-covered paws, the snow leopard suffers no penalties for moving through snow-covered terrain."}],"description":"Snow leopards are relatives of the common leopard and are found in the coldest regions of the world, inhabiting mountain ranges and snowy coniferous forests. Their lairs are typically rocky shelters lined with their own fur for warmth.\n\nSnow leopards are strong, agile, nocturnal hunters and their diet consists of livestock, wild boars, hares, and deer. Like most other big cats, they stalk and ambush their prey. Slain prey is dragged back to the lair and devoured over a period of several days.\n\nSnow leopards are generally solitary creatures, though during mating season more than one can be encountered. A den typically contains 1d2 adults and 1d4 cubs. Cubs that are captured can be sold on the market for 500 gp or more.\n\nA snow leopard is about five ft. long with light gray or smoke gray fur that turns white on its underbelly. Its fur is covered with large rings that contain smaller and darker spots of dark gray or black. Its fur is over one inch thick and provides it with warmth against the harshest of temperatures. Eyes are gray or dark blue. Its paws are large and thickfurred which enables it to maintain its footing on the most treacherous of snow-covered ground.\n\nSnow leopards are hunted by many races for their fur which can be sold to furriers and made into coats, blankets, and so on. A typical male's coat fetches about 800 gp on the market.\n\nSnow leopards, unlike other great cats, don't roar. Rather they let out a low, soft moan. They attack from a distance leaping or pouncing on a foe and attacking with their claws and bite.","ecology":"","habitat_society":""},{"name":"Solifugid","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 Dex, +3 natural","hp":27,"hd":"5d8+5","hdvalue":5,"fort":5,"ref":3,"will":1,"speed":[{"type":"land","speed":30}],"melee":"2 pincers +6 (1d6+3 plus grab), bite +6 (1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d6+3"}],"strength":16,"dexterity":14,"constitution":13,"wisdom":10,"charisma":2,"baseatk":3,"cmb":6,"cmb_special":"+4 vs. grab","cmd":18,"cmd_special":"+12 vs. trip","skills":[{"skill":"Perception","value":4}],"environments":["warm land"],"organizations":["solitary","colony (2-5)"],"treasure":"none","description_visual":"This spiderlike creature has ten leg, the front two ending in sucker-like clamps. Its front sports two spider-like eyes and a set of large, oversized mandibles.","group":"False Spider","source":"Tome of Horrors Complete (3pp)","description":"Solifugids, also known as camel spiders, are at least 6 ft. long but can grow to a length of 12 ft.","ecology":"","habitat_society":"","credit":"The Pedipalp and Solifugid originally appeared in module Q1 Queen of the Demonweb Pits and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and are used by permission."},{"name":"Stench Kow","cr":3,"xp":800,"alignment":"N","size":"Large","type":"magical beast","subtypes":["extraplanar"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["stench (DC 14, 5 rounds)"],"ac":17,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"+0 Dex, +8 natural, -1 size","hp":25,"hd":"3d10+9","hdvalue":3,"fort":6,"ref":3,"will":2,"immunities":["cold","fire","poison"],"speed":[{"type":"land","speed":40}],"melee":"gore +6 (1d8+6)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"powerful charge"},{"type":"trample","details":"1d8+6, DC 15"}],"strength":18,"dexterity":10,"constitution":17,"intelligence":2,"wisdom":12,"charisma":4,"baseatk":3,"cmb":8,"cmd":18,"cmd_special":"+4 vs. trip","feats":[{"feat":"Great Fortitude"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":10}],"environments":["any (Lower Planes; usually Nine Hells)"],"organizations":["herd (15-60, 50% noncombatant young, plus one 6 HD bull per 5 female adults)"],"treasure":"none","description_visual":"This creature resembles a large bison with a hunched back, long downward-curving horns, and grotesque facial features.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Powerful Charge","kind":"Ex","details":"On a successful charge attack, a stench kow deals double damage with its gore. This damage is tripled (not quadrupled) on a critical hit."}],"description":"The stench kow is the cattle of the lower planes. Found mainly in the Hells, stench kows are a race of bison-like creatures, not unlike the normal cattle found on the Material Plane. They are used as food by the denizens of the lower planes and are often found in large herds wandering the wastelands of the nether regions. Stench kows attack only if threatened, if the herd is threatened, or if the young calves are in danger. A stench kow attacks by charging and trampling, or butting its opponents with its horns.\n\nA typical stench kow is 8 ft. long and weighs about 3,000 pounds. Its fur is orange or brown in color and mottled green throughout.","ecology":"","habitat_society":"","credit":"The Stench Kow originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Strangle Weed","cr":3,"xp":800,"alignment":"N","size":"Large","type":"plant","subtypes":["aquatic"],"init":0,"senses":[{"type":"blindsight","modifier":"30 ft."},{"type":"low-light vision"}],"ac":14,"ac_touch":9,"ac_flat_footed":14,"ac_mods":"+5 natural, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":1,"will":2,"defensive_abilities":["camouflage"],"immunities":["plant traits"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"swim","speed":5}],"melee":"slam +7 (1d6+6 plus grab)","space":"10 ft.","reach":"20 ft.","special_attacks":[{"type":"constrict","details":"1d6+6"},{"type":"fronds"}],"strength":18,"dexterity":10,"constitution":16,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":3,"cmb":8,"cmb_special":"+4 vs. grapple","cmd":18,"cmd_special":"can't be tripped","feats":[{"feat":"Power Attack"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Perception","value":6},{"skill":"Stealth","value":1},{"skill":"Swim","value":15}],"environments":["temperate aquatic","warm aquatic"],"organizations":["solitary","patch (2-4)"],"treasure":"50% coins, 1/10th goods, 1/10th items","description_visual":"This mass of writhing vines and leaves looks like a large patch of seaweed. Several long fronds protrude from the center of it.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Camouflage","kind":"Ex","details":"Since a strangle weed looks like normal seaweed when at rest, it takes a DC 20 Perception check to notice it before it attacks. Anyone with ranks in Survival or Knowledge (nature) can use one of those skills instead of Perception to notice the plant."},{"type":"Fronds","kind":"Ex","details":"Strangle weed attacks with fronds that can extend up to 20 ft. from its central mass. Each strangle weed has 3-12 fronds. A strangle weed attacks with these fronds as a slam attack; although it can make only one attack per round, if it grapples a foe it isn't denied its Dexterity bonus against non-grappled foes and can still make attacks of opportunity if it has any free fronds. Once a foe is grappled, the strangle weed can attempt to latch on 1-4 additional fronds each round as a standard action by means of a separate grapple check. Additional fronds attached to a foe don't do increased damage, but they do add a cumulative +2 bonus to the strangle weed's CMB on subsequent grapple checks against that foe. To free itself, the foe must succeed on a grapple check against every frond grappling it."}],"description":"The strangle weed is a large plant that resembles a patch of seaweed.\n\nStrangle weed is an ambush predator, relying on its similarity to seaweed to remain inconspicuous until prey wanders near, whereupon it lashes out with its fronds, attempting to grapple its foes, then pull them beneath the water and crush them.\n\nA subterranean version of the strangle weed is believed to exist, though encounters with it are very rare. It is dark blackish-green and is found in underground pools, stagnant water, and the like.\n\nA typical strangle weed is 12 ft. in diameter, dark green and slightly slimy, with long, ropy fronds, each about ten ft. long, radiating from its central mass. The strangle weed keeps these fronds concealed within its main mass when hiding from potential prey.","ecology":"","habitat_society":"","credit":"The Strangle Weed originally appeared in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission."}];
